/// 실행 중인 단계의 tmux 창을 닫고 실패로 기록한다.
func cancel(_ job: JobSnapshot) {
    guard let (step, round) = job.activeStep else { return }
    Tmux.killWindow(session: session(job.agent(step, round)).tmuxSession, name: windowName(job, step, round))
    recordFailure(job, step, round, "사용자가 중단했어요")
    refresh(job.id)
}

/// 실패한 단계의 기록을 시도(attempt)로 옮겨 두고 그 단계부터 다시 진행한다.
/// 옮기지 못하면 결과가 그대로 남아 실패로 보이고, 다시 시작하지 않는다.
func retry(_ job: JobSnapshot) {
    guard case .failed = job.phase else { return }
    if job.meta.design != true, job.meta.mode == .review, job.rounds.count == 1, job.rounds[0].plan?.ok != true {
        migrateLegacyPlan(job)
        return
    }
    do {
        try retryFailedStep(job)
    } catch {
        lastError = "지난 시도 기록을 옮기지 못해 다시 시작하지 않았어요: \(error.localizedDescription)"
        refresh(job.id)
        return
    }
    lastError = nil
    refresh(job.id)
    startLoopIfNeeded()
}

/// 예전 순서(Claude 계획)의 계획 단계에서 멈춘 작업을 새 순서(Codex 설계부터)로 옮겨 다시 시작한다.
/// 아직 돌고 있을 수 있는 Claude 계획 창을 닫고, 그 에이전트 프로세스가 정말 끝난 뒤에야 plan-1 파일을 지우고 옮긴다 —
/// 끝나는 중이던 예전 에이전트가 새 Codex 설계의 plan-1 파일을 덮어쓰지 않게.
/// 창이 사라졌는데 결과가 없으면 (앱 밖에서 닫았거나 tmux 가 재시작됨) 실패로 기록한다.
private func checkAlive(_ job: JobSnapshot, _ step: JobStep, _ round: Int) {
    guard !Tmux.windowNames(session: session(job.agent(step, round)).tmuxSession).contains(windowName(job, step, round)) else { return }
    recordFailure(job, step, round, "작업 창이 닫혀서 중단됐어요")
}

/// 앱이 본 실패를 그 단계의 결과로 남긴다 (담당 CLI 는 배치 기준). 남기지 못하면 앱 오류로 알린다 — 성공으로 넘어가지 않는다.
private func recordFailure(_ job: JobSnapshot, _ step: JobStep, _ round: Int, _ message: String) {
    let url = job.files.result(step, round)
    // 창이 닫히기 직전에 agent 가 결과를 남겼을 수 있다.
    guard !FileManager.default.fileExists(atPath: url.path) else { return }
    var result = StepResult(role: step, agent: job.agent(step, round), ok: false, error: message)
    result.requestedModel = job.placement(step, round)?.model
    do {
        try JobJSON.save(result, to: url)
    } catch {
        lastError = "\(step.rawValue)-\(round) 실패를 기록하지 못했어요 (\(message)): \(error.localizedDescription)"
    }
}

private func windowName(_ job: JobSnapshot, _ step: JobStep, _ round: Int) -> String {
    "job-\(job.id.suffix(6))-\(step.rawValue)\(round)"
}
